def get_html():
    return zlib.decompress(base64.b85decode(_PAYLOAD)).decode("utf-8")

def main():
    html = get_html()
    try:
        from streamlit.runtime.scriptrunner import get_script_run_ctx
        active = get_script_run_ctx(suppress_warning=True) is not None
    except ImportError:
        active = False
    if active:
        import streamlit as st
        import streamlit.components.v1 as components
        st.set_page_config(page_title="SM64 플레이", layout="wide")
        components.html(html, height=950, scrolling=True)
        return
    try:
        from IPython import get_ipython
        notebook = get_ipython() is not None
    except ImportError:
        notebook = False
    if notebook:
        from IPython.display import HTML, display
        import html as escaping
        display(HTML('<iframe style="width:100%;height:950px;border:0" srcdoc="'
                     + escaping.escape(html, quote=True) + '"></iframe>'))
        return
    import argparse
    from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
    parser = argparse.ArgumentParser(description="SM64 플레이")
    parser.add_argument("--port", type=int, default=8000)
    args = parser.parse_args()
    body = html.encode("utf-8")
    class Handler(BaseHTTPRequestHandler):
        def do_GET(self):
            if self.path not in ("/", "/index.html"):
                self.send_error(404)
                return
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
    try:
        server = ThreadingHTTPServer(("127.0.0.1", args.port), Handler)
    except OSError as exc:
        raise SystemExit(f"서버를 시작할 수 없습니다: {exc}. --port 8001로 다른 포트를 지정해 주세요.")
    print(f"브라우저에서 http://localhost:{args.port} 를 여세요. 종료: Ctrl+C")
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()

if __name__ == "__main__":
    main()
